struct Arena {
    std::byte* base;
    std::size_t capacity;
    std::size_t offset = 0;

    void* alloc(std::size_t size, std::size_t align) {
        std::size_t start = (offset + align - 1) & ~(align - 1);
        if (start + size > capacity) return nullptr;
        offset = start + size;
        return base + start;
    }
    void reset() { offset = 0; }
};
