steps.body:
A pool preallocates `N` slots of one type. Free slots form a linked list threaded **through the free slots themselves**, so the list costs no extra memory:

```cpp
template <class T, std::size_t N>
class Pool {
    union Slot { T value; Slot* next; Slot() {} ~Slot() {} };
    Slot slots[N];
    Slot* freeHead = nullptr;
public:
    Pool() {
        for (std::size_t i = 0; i < N; ++i) { slots[i].next = freeHead; freeHead = &slots[i]; }
    }
    T* create() {
        if (!freeHead) return nullptr;            // pool is full
        Slot* s = freeHead;
        freeHead = s->next;                       // pop the free list: O(1)
        return new (&s->value) T{};               // build the object in place
    }
    void destroy(T* p) {
        p->~T();
        Slot* s = reinterpret_cast<Slot*>(p);
        s->next = freeHead;                       // push onto the free list: O(1)
        freeHead = s;
    }
};
```

In a test with a 3-slot pool, a fourth `create()` returned `nullptr` (full), and after destroying the second bullet, the next `create()` got exactly its slot back. Pools pair naturally with generational handles: the slot index is the handle's index.

