int countAlive(const std::vector<Enemy>& enemies) {
    int alive = 0;
    std::vector<std::thread> workers;
    const std::size_t chunk = enemies.size() / 4;
    for (int w = 0; w < 4; ++w) {
        workers.emplace_back([&, w] {
            for (std::size_t i = w * chunk; i < (w + 1) * chunk; ++i)
                if (enemies[i].hp > 0) ++alive;
        });
    }
    for (auto& t : workers) t.join();
    return alive;
}
